/** An agent's own mark, by the slug the skills CLI knows it by; `fallback` shows for an agent with none. */
export function AgentIcon({
  slug,
  fallback,
  className,
}: {
  slug: string;
  fallback: ReactNode;
  className?: string;
}) {
  const agent = AGENT_ICONS[slug];
  if (!agent) return fallback;
  if (agent.svg) {
    return (
      <span
        aria-hidden
        className={cn(
          "text-foreground flex size-5 [&_svg]:size-full",
          className,
        )}
        dangerouslySetInnerHTML={{ __html: agent.svg }}
      />
    );
  }
  if (agent.emoji) {
    return (
      <span
        aria-hidden
        className={cn(
          "flex size-5 items-center justify-center text-base leading-none",
          className,
        )}
      >
        {agent.emoji}
      </span>
    );
  }
  if (agent.src) {
    return (
      <img
        src={agent.src}
        alt=""
        className={cn(
          "size-5 object-contain",
          agent.invert && "dark:invert",
          className,
        )}
      />
    );
  }
  return fallback;
}
